  Theorem put_spec : ltac2:(zQ "h40!h9!hgc!hv2!js0!ig9!js6!ju4!hf!ii9!kib!kj8!kne!ks3!io9!ip9!iu6!jj0!jna!ksa!hvb>2t0@1$1@1$0#k0>2t1@1$1@1$0#k0>2t2@1$1@1$0#k0>2a4@1$1@1$0#k0>2a5@1$1@1$0#k0>2a6@1$1@1$0#k0>2a7@1$1@1$0#k0>2t3@1$1@1$0#k0>2t4@1$1@1$0#k0>2t5@1$1@1$0#k0>2t6@1$1@1$0#k0>0@3$8$2?1d?1m>0@4$b$2?1m?2TR@3$5@1$1@1$0#k0@4$6$7@1$1@1$0#k0$3?1T?4rest>0@4$e$2?1m?2lo@2$h3@1$0#k0?2sp>0@2$h0$2?1m@3$c$2@h7$a?2ra?2sp?2gp?2tp?2s0?2s1?2s2?2s3?2s4?2s5?2s6?2s7?2s8?2s9?3s10?3s11?1F?2fc?2lo?1d?1h?1n?1m@7$f@hf$d?2ra?2sp?2gp?2tp^f^e^d?2s0?2s1@1$3+iqihh8@1$3?2TR@1$3?1n@1$3Z^c^b^a^9?2s2?2s3?2s4?2s5?2s6?2s7?2s8?2s9?3s10?3s11^8^7^6^5?1F@2$h2@1$0#k0$9?2fc@1$4@1$1@1$0#k0?1m@1$h1$2").
